CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authors (id TEXT PRIMARY KEY, name_ar TEXT NOT NULL, name_normalized TEXT NOT NULL, death_hijri INTEGER, biography TEXT NOT NULL DEFAULT '', UNIQUE(name_normalized));
CREATE TABLE IF NOT EXISTS works (id TEXT PRIMARY KEY, title_ar TEXT NOT NULL, title_normalized TEXT NOT NULL, match_key TEXT NOT NULL UNIQUE, category TEXT NOT NULL DEFAULT 'other', metadata_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_authors (work_id TEXT NOT NULL REFERENCES works(id), author_id TEXT NOT NULL REFERENCES authors(id), role TEXT NOT NULL DEFAULT 'author', PRIMARY KEY(work_id,author_id,role));
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name_ar TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_categories (work_id TEXT NOT NULL REFERENCES works(id), category_id TEXT NOT NULL REFERENCES categories(id), PRIMARY KEY(work_id,category_id));
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, cursor TEXT, enabled INTEGER NOT NULL DEFAULT 0, schedule_hours INTEGER NOT NULL DEFAULT 168, next_sync_at TEXT);
CREATE TABLE IF NOT EXISTS editions (id TEXT PRIMARY KEY, work_id TEXT NOT NULL REFERENCES works(id), source_id TEXT NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, revision TEXT NOT NULL, publisher TEXT NOT NULL DEFAULT '', editor TEXT NOT NULL DEFAULT '', publication_year INTEGER, status TEXT NOT NULL DEFAULT 'pending-review', created_at TEXT NOT NULL, page_count INTEGER NOT NULL DEFAULT 0, source_url TEXT NOT NULL, UNIQUE(source_id,external_id,revision));
CREATE TABLE IF NOT EXISTS source_records (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, edition_id TEXT NOT NULL REFERENCES editions(id), revision TEXT NOT NULL, raw_json TEXT NOT NULL, discovered_at TEXT NOT NULL, UNIQUE(source_id,external_id,revision));
CREATE TABLE IF NOT EXISTS rights_records (id TEXT PRIMARY KEY, edition_id TEXT NOT NULL UNIQUE REFERENCES editions(id), status TEXT NOT NULL DEFAULT 'pending-review', allow_hosting INTEGER NOT NULL DEFAULT 0, allow_download INTEGER NOT NULL DEFAULT 0, license_url TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL DEFAULT '', attribution TEXT NOT NULL DEFAULT '', reviewed_by TEXT, reviewed_at TEXT, expires_at TEXT);
CREATE TABLE IF NOT EXISTS book_files (id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id), format TEXT NOT NULL, storage_key TEXT NOT NULL, checksum TEXT NOT NULL, size_bytes INTEGER NOT NULL, original_name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(edition_id,checksum));
CREATE TABLE IF NOT EXISTS book_pages (edition_id TEXT NOT NULL REFERENCES editions(id), seq INTEGER NOT NULL, part TEXT NOT NULL DEFAULT '', page_no TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, body_normalized TEXT NOT NULL, footnotes TEXT NOT NULL DEFAULT '', PRIMARY KEY(edition_id,seq));
CREATE TABLE IF NOT EXISTS book_sections (id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id), title TEXT NOT NULL, seq INTEGER NOT NULL, parent_seq INTEGER);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookmarks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), work_id TEXT NOT NULL REFERENCES works(id), edition_id TEXT REFERENCES editions(id), seq INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', quote TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(user_id,work_id,seq));
CREATE TABLE IF NOT EXISTS reading_progress (user_id TEXT NOT NULL REFERENCES users(id), edition_id TEXT NOT NULL REFERENCES editions(id), seq INTEGER NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(user_id,edition_id));
CREATE TABLE IF NOT EXISTS collections (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS collection_works (collection_id TEXT NOT NULL REFERENCES collections(id) ON DELETE CASCADE, work_id TEXT NOT NULL REFERENCES works(id), position INTEGER NOT NULL, PRIMARY KEY(collection_id,work_id));
CREATE TABLE IF NOT EXISTS sync_runs (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), status TEXT NOT NULL, discovered INTEGER NOT NULL DEFAULT 0, error TEXT, started_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, dedup_key TEXT NOT NULL UNIQUE, type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, lease_until TEXT, lease_token TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, target_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS pages_normalized ON book_pages(edition_id,seq);
CREATE INDEX IF NOT EXISTS editions_work ON editions(work_id,status);
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(status,available_at);
CREATE INDEX IF NOT EXISTS bookmarks_user ON bookmarks(user_id);
CREATE INDEX IF NOT EXISTS sections_edition ON book_sections(edition_id,seq);
